function travelerIdentityEligibleKind(kind){return ['merchant','mercenary','refugees','coalition','redstone','bluestone','spawn'].includes(kind)}
function travelerIdentityKnown(r){if(!r)return false;const s=r.social||{};return (s.familiarity||0)>=2||(r.contractsCompleted||0)>0||(r.helped||0)>=2||(r.contracts||0)>=1||(r.meetings||0)>=3}
function travelerPersonName(sex='neutral',surname='',used=[]){const pool=TRAVELER_PERSON_NAMES[sex]||TRAVELER_PERSON_NAMES.neutral;for(let i=0;i<30;i++){const first=pick(pool),name=surname?`${first} ${surname}`:first;if(!used.includes(name))return name}return `${pick(pool)} ${surname||rnd(2,99)}`}
function travelerMember(id,name,role,age='adult',note='',sex='neutral'){return {id,name,role,age,note,sex}}
