 const surname=pick(TRAVELER_SURNAMES),used=[],mk=(sex,role,age='adult',note='')=>{const name=travelerPersonName(sex,surname,used);used.push(name);return travelerMember(`person_${uid()}`,name,role,age,note,sex)};
